using System;
using System.Collections.Generic;

namespace FHSolver.Solver
{
    /// <summary>
    /// 敌人移动预测（P5 精确化）—— **纯函数**，不引用任何游戏类型。
    ///
    /// ═══════════════════════════════════════════════════════════════════
    /// 为什么还要再写一个，而不直接用 <c>Bridge/EnemyPredictor</c>：
    ///   那个类依赖 CScenario / CActor / Geometry 等**游戏类型**，
    ///   而 StateAdvancer 是纯计算层（不引用游戏类型，测试台才能直接编译它）。
    ///   所以这里复刻同一套规则，但输入改成**委托**（P1Context 本来就有）。
    ///
    /// 复刻的是游戏真实的 AI 选位规则（CAIMoveNew，反编译实证）：
    ///   ① 焦点 = 与它敌对的存活单位中，**能打到它所需的移动代价**最小者
    ///      （`lowestMoveCostToAttack` 升序 → hexDist 升序 → 先攻；无随机 tie-break）
    ///   ② 落点 = 可达格里「能打到焦点」且「移动代价最小」的那一格
    ///   ③ 现在站的格子就能打到焦点 → **它不动**（代价 0 已经最小）
    ///
    /// 与上一版「射程 + 移动力 取上界」的区别：
    ///   旧：dist <= AttackRange + MoveStrength 就算够得着 → 纯几何，**会高估**
    ///       （隔着一堵墙、或者根本没有路，也会算成能打到你）
    ///   新：真的去寻路，看**是否存在**一个可达格能打到目标 → 考虑了地形、占用、视线
    /// ═══════════════════════════════════════════════════════════════════
    /// </summary>
    /// <summary>
    /// 怪物这一回合的移动意图。
    ///
    /// ⚠ 这个枚举的存在本身就是一次**纠正**：
    ///   我原先以为"找不到攻击位 → 原地不动"，反编译后发现是错的 ——
    ///   CAIMoveNew.FindPathToFocus() 有明确的 fallback：
    ///   走不到最佳攻击位时，会在**所有可达格**里找一个"离攻击位最近"的格子走过去。
    ///   也就是 Gloomhaven/Frosthaven 的标准规则：**够不着也会尽量靠近焦点**。
    /// </summary>
    internal enum EnemyMovePlan
    {
        /// <summary>不动（移动力为 0，或没有任何可达格）。</summary>
        None,

        /// <summary>能走到一个「可以打到焦点」的格子 → 移动后攻击。</summary>
        Attack,

        /// <summary>走不到任何攻击位 → 朝焦点**靠近**，但这回合不攻击、不抽牌。</summary>
        Approach,
    }

    internal static class EnemyPathing
    {
        /// <summary>一个候选目标。Name 只用于输出。</summary>
        public struct Target
        {
            public int X;
            public int Y;
            public string Name;

            /// <summary>目标的先攻（同距时用来 tie-break，照抄 ActorInitiativeComparer）。</summary>
            public int Initiative;

            public Target(int x, int y, string name, int initiative = int.MaxValue)
            {
                X = x; Y = y; Name = name; Initiative = initiative;
            }
        }

        /// <summary>
        /// 给一个敌人规划「这一回合会走到哪、打谁」。
        /// </summary>
        /// <param name="fromX">它现在的位置</param>
        /// <param name="fromY">它现在的位置</param>
        /// <param name="movePoints">本回合移动力（意图上的 Move；负数已折算过）</param>
        /// <param name="attackRange">攻击射程</param>
        /// <param name="reachable">可达格查询（含危险地形伤害的第三项）</param>
        /// <param name="rangeDistance">格间距离（走寻路，含门/地形的真实距离）</param>
        /// <param name="hasLOS">视线判定</param>
        /// <param name="targets">候选目标（我方单位）</param>
        /// <param name="blocked">被占用的格子（其他单位；**不含它自己**）</param>
        /// <param name="toX">输出：落点</param>
        /// <param name="toY">输出：落点</param>
        /// <param name="focusIdx">输出：焦点在 targets 里的下标；-1 = 打不到任何人</param>
        /// <param name="preferFurthest">
        /// `MiscAbilityData.AttackFurthestTarget`（游戏里的「攻击最远目标」怪）。
        /// 为 true 时焦点先按 hexDist **降序**（CompareEnemiesUsingFurthesFocus）。
        /// </param>
        /// <returns>移动意图（Attack / Approach / None）</returns>
        public static EnemyMovePlan PlanMove(
            int fromX, int fromY,
            int movePoints,
            int attackRange,
            Func<int, int, int, List<(int X, int Y, int Hazard)>> reachable,
            Func<int, int, int, int, int> rangeDistance,
            Func<int, int, int, int, bool> hasLOS,
            List<Target> targets,
            HashSet<(int, int)> blocked,
            out int toX, out int toY, out int focusIdx,
            bool preferFurthest = false)
        {
            toX = fromX;
            toY = fromY;
            focusIdx = -1;

            if (targets == null || targets.Count == 0) return EnemyMovePlan.None;
            if (attackRange < 0) return EnemyMovePlan.None;

            // ---- 候选落点：可达格 + 原地不动 ----
            var spots = new List<(int X, int Y)> { (fromX, fromY) };

            if (movePoints > 0 && reachable != null)
            {
                List<(int X, int Y, int Hazard)> reach;
                try { reach = reachable(fromX, fromY, movePoints); }
                catch { reach = null; }

                if (reach != null)
                {
                    foreach ((int X, int Y, int HAZ) t in reach)
                    {
                        if (t.X == fromX && t.Y == fromY) continue;      // 已在 spots 里
                        if (blocked != null && blocked.Contains((t.X, t.Y))) continue;
                        spots.Add((t.X, t.Y));
                    }
                }
            }

            if (rangeDistance == null) return EnemyMovePlan.None;

            // ---- ① 每个目标的「攻击代价 / 距离 / 先攻」----
            //   游戏 CAIMoveNew.CompareEnemies（反编译实证，无随机 tie-break）：
            //     isFocusOverride 降序 → lowestMoveCostToAttack 升序
            //     → hexDist 升序 → 调整后先攻
            //   其中 hexDist = 地形感知的**路径长度**（忽略单位），
            //   lowestMoveCostToAttack = 走到**任一攻击位**的最小移动代价。
            //
            //   ⚠ v1.31 把焦点简化成"路径距离最近"，维度不对：
            //     隔困难地形/绕墙时，"最近"和"打它最省移动力"会指向不同目标。
            //     这里按三级键照抄游戏；move cost 用 rangeDistance 近似（不额外计困难地形双倍）。
            int n = targets.Count;
            var dist = new int[n];
            var cost = new int[n];
            var spotX = new int[n];
            var spotY = new int[n];

            for (int ti = 0; ti < n; ti++)
            {
                dist[ti] = rangeDistance(fromX, fromY, targets[ti].X, targets[ti].Y);
                cost[ti] = int.MaxValue;
                spotX[ti] = -1;
                spotY[ti] = -1;
            }

            foreach ((int X, int Y) s in spots)
            {
                int costToSpot = rangeDistance(fromX, fromY, s.X, s.Y);
                if (costToSpot < 0) continue;

                for (int ti = 0; ti < n; ti++)
                {
                    if (cost[ti] <= costToSpot) continue;             // 已有更省的攻击位

                    int r = rangeDistance(s.X, s.Y, targets[ti].X, targets[ti].Y);
                    if (r < 0 || r > attackRange) continue;
                    if (hasLOS != null && !hasLOS(s.X, s.Y, targets[ti].X, targets[ti].Y)) continue;

                    cost[ti] = costToSpot;
                    spotX[ti] = s.X;
                    spotY[ti] = s.Y;
                }
            }

            // ---- ② 焦点（CompareEnemies / CompareEnemiesUsingFurthesFocus）----
            int bestFocus = -1;
            for (int ti = 0; ti < n; ti++)
            {
                if (dist[ti] < 0) continue;                            // 完全没有路径
                if (bestFocus < 0 || BetterFocus(ti, bestFocus, targets, dist, cost, preferFurthest))
                {
                    bestFocus = ti;
                }
            }
            if (bestFocus < 0) return EnemyMovePlan.None;
            Target focus = targets[bestFocus];

            // ---- ③ 能打到焦点 → 走到最省的攻击位（原地代价 0，自然不动）----
            if (cost[bestFocus] < int.MaxValue)
            {
                toX = spotX[bestFocus];
                toY = spotY[bestFocus];
                focusIdx = bestFocus;
                return EnemyMovePlan.Attack;
            }

            // ---- ④ 打不到任何人 → **朝焦点靠近**（真实 AI 的 fallback，不是原地不动）----
            //    CAIMoveNew.FindPathToFocus：走不到 bestAttackTile 时，
            //    会在所有可达格里挑一个"离攻击位最近"的走过去（InitReachableTiles + 代价比较）。
            //    这里简化为「离**焦点本人**最近的可达格」—— 攻击位本来就是焦点旁边的格子，
            //    两者在绝大多数场景下等价，且更好解释。
            if (movePoints <= 0) return EnemyMovePlan.None;

            int bestD = dist[bestFocus];          // 必须比"现在到焦点的距离"更近才值得动
            int bx = fromX, by = fromY;
            bool found = false;
            foreach ((int X, int Y) s in spots)
            {
                if (s.X == fromX && s.Y == fromY) continue;
                int d = rangeDistance(s.X, s.Y, focus.X, focus.Y);
                if (d >= 0 && d < bestD) { bestD = d; bx = s.X; by = s.Y; found = true; }
            }

            // ⚠ 不能用 x/y == -1 当"没找到"的哨兵：
            //   六边形地图的坐标可以是负的（实测 (-1,1) 就是合法格）。
            if (!found) return EnemyMovePlan.None;

            toX = bx;
            toY = by;
            focusIdx = bestFocus;
            return EnemyMovePlan.Approach;
        }

        /// <summary>
        /// 焦点排序：<c>dist</c> 是六边形路径距离，<c>cost</c> 是"走到攻击位的最小代价"。
        /// 与游戏 <c>CompareEnemies</c> 一致：cost 升序 → dist 升序 → 先攻升序；
        /// <c>preferFurthest</c>（AttackFurthestTarget）时先按 dist **降序**。
        /// </summary>
        private static bool BetterFocus(int i, int j, List<Target> targets,
            int[] dist, int[] cost, bool preferFurthest)
        {
            if (preferFurthest && dist[i] != dist[j]) return dist[i] > dist[j];

            if (cost[i] != cost[j]) return cost[i] < cost[j];
            if (dist[i] != dist[j]) return dist[i] < dist[j];
            return targets[i].Initiative < targets[j].Initiative;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using AStar;
using FHSolver.Model;
using FHSolver.Solver;
using ScenarioRuleLibrary;

namespace FHSolver.Bridge
{
    /// <summary>
    /// 敌人落点预测（P4）—— **只读**，不掷任何骰子。
    ///
    /// ════════════════════════════════════════════════════════════════
    /// 前提：怪物 AI **完全确定性**，不存在随机性。
    ///
    /// 证据（反编译实证）：
    ///   `CAIMoveNew.cs`    1975 行，Random 出现 **0** 次
    ///   `CMonsterClass.cs` 1330 行，Random 出现 **0** 次
    ///   `CEnemyActor.cs`    751 行，Random 出现 **0** 次
    ///
    /// 全库 Random 只出现在：宝箱/战利品的随机内容、怪物修正牌堆洗牌、
    /// 传送落点、关卡脚本与场景物件摆放 —— **都不进入 AI 决策**。
    ///
    /// 怪物决策链 CAIMoveNew.Process() 全程确定性：
    ///   ResolveFocusOverride → ResolveAttackAbility → InitPathfinderContext
    ///   → AddActorsToPathFinderAndEnemyEvals → FloodFill
    ///   → CalculateValidAttackTilesForAllEnemies → SortEnemyEvals
    ///   → FindBestAttackPositionForTheFocus → FindPathToFocus → CalcWaypoints
    ///
    /// 焦点排序 CompareEnemies 是纯比较、无随机 tie-break：
    ///   isFocusOverride 降序 → lowestMoveCostToAttack 升序 → hexDist 升序
    ///   → GameState.s_ActorAdjustedInitiativeComparer（先攻）
    ///
    /// ⚠ 唯一真正随机的场景：怪物行动牌堆空了要洗牌
    ///   `m_AbilityCards.Shuffle(CurrentScenarioState.EnemyAbilityRNG)`
    ///   这个 RNG 状态随存档持久化、且 SharedLibrary.Random 是
    ///   .NET System.Random 的逐行拷贝，可离线复刻（见 MODIFIER.md）。
    /// ════════════════════════════════════════════════════════════════════
    ///
    /// 复刻的规则：
    ///   ① 焦点 = 与它敌对的存活单位中，「走到能攻击到它的位置所需代价」最小者
    ///   ② 落点 = 可达格里「能打到焦点」且「离自己最近」的格子
    ///   ③ 若现在站的格子就已经能打到焦点 → 它不动
    /// </summary>
    internal static class EnemyPredictor
    {
        /// <summary>一次预测结果：这个敌人移动之后会站在哪。</summary>
        public sealed class Prediction
        {
            public string Guid;
            public string DisplayName;
            public int FromX, FromY;
            public int ToX, ToY;

            /// <summary>本回合移动力（负数已折算成怪物基础移动力）。</summary>
            public int MovePoints;

            /// <summary>该单位的先攻（数值小的先动）。</summary>
            public int Initiative;

            public bool HasAttack;
            public int AttackRange;
            public int AttackStrength;

            /// <summary>它要打谁（焦点）。</summary>
            public string FocusName = "(无)";

            /// <summary>
            /// 它这次攻击会**施加**给目标的负面条件（缴械/中毒/静足/眩晕…）。
            /// 读自行动卡的 `CAbility.NegativeConditions`。
            /// </summary>
            public List<string> AppliesNegative = new List<string>();

            /// <summary>预测它会不会离开现在的格子。</summary>
            public bool WillMove;
        }

        /// <summary>
        /// 预测所有敌对单位「本回合结束时会站在哪」。
        ///
        /// 时序正确性的关键：怪物执行自己回合时，玩家还没执行本回合移动，
        /// 所以怪物的落点只依赖玩家的**起始站位** —— 是已知量。
        ///
        /// 这里按先攻顺序逐个推进怪物，已移动的怪物会把它的落点计入占用，
        /// 于是后动的怪物不会撞到先动怪物的新位置。
        /// </summary>
        public static List<Prediction> Predict(CScenario scenario)
        {
            var list = new List<Prediction>();
            if (scenario == null) return list;

            var alive = new List<CActor>();
            try
            {
                foreach (CActor x in scenario.AllAliveActors)
                {
                    if (x != null) alive.Add(x);
                }
            }
            catch (Exception e)
            {
                Plugin.Log?.LogWarning($"[FHSolver] 读取存活单位失败: {e.Message}");
                return list;
            }

            // 收集所有敌对单位及其先攻
            var enemies = new List<UnitRef>();
            foreach (CActor a in alive)
            {
                try
                {
                    if (!(a is CEnemyActor enemy)) continue;
                    if (enemy.MonsterClass == null) continue;

                    UnitSnapshot u = StateReader.ReadUnit(a, isPlayer: false);
                    if (!u.IsHostileToPlayer) continue;

                    int init = u.Initiative == 0 ? u.InitiativePredicted : u.Initiative;
                    enemies.Add(new UnitRef { Actor = a, Snap = u, X = u.X, Y = u.Y, Initiative = init });
                }
                catch { /* 单个单位跳过 */ }
            }

            // 初始占用：所有非敌对单位 + 所有敌人（后动者会原地不动）
            var occupied = new HashSet<(int, int)>();
            foreach (CActor a in alive)
            {
                Point p;
                try { p = a.ArrayIndex; } catch { continue; }
                if (p != null) occupied.Add((p.X, p.Y));
            }

            // ★ 焦点规则现在要算「走到每个攻击位的代价」，同一个 Insert 里
            //   不同敌人会反复查同样的格子对 —— 用局部缓存挡掉重复 A*。
            var distCache = new Dictionary<(int, int, int, int), int>();
            Func<int, int, int, int, int> dist = (x1, y1, x2, y2) =>
            {
                var key = (x1, y1, x2, y2);
                int v;
                if (distCache.TryGetValue(key, out v)) return v;
                v = Geometry.RangeDistance(x1, y1, x2, y2);
                distCache[key] = v;
                return v;
            };

            foreach (UnitRef e in enemies.OrderBy(x => x.Initiative))
            {
                ActionSnapshot intent = e.Snap.Intent;
                if (intent == null) continue;

                int move = intent.HasMove ? intent.MoveStrength : 0;
                if (move < 0)
                {
                    try { move = (e.Actor as CEnemyActor)?.MonsterClass?.Move ?? 0; }
                    catch { move = 0; }
                }
                if (move <= 0) continue;                       // 不走就原地不动，占用集已经包含它

                // 候选目标：与它敌对的存活单位（含玩家/盟友/召唤物）。
                // 只取焦点排序需要的字段，**不调 StateReader.ReadUnit**
                // （那会为每个目标重复读手牌/牌堆，怪多时是明显的浪费）。
                var targets = new List<EnemyPathing.Target>();
                var names = new List<string>();
                foreach (CActor other in alive)
                {
                    if (other == e.Actor) continue;
                    bool isEnemy;
                    try { isEnemy = CActor.AreActorsEnemies(e.Actor.Type, other.Type, e.Actor, other); }
                    catch { continue; }
                    if (!isEnemy) continue;

                    Point op;
                    try { op = other.ArrayIndex; } catch { continue; }
                    if (op == null) continue;

                    bool dead = true;
                    try { dead = other.IsDead; } catch { /* 拿不准就当活的 */ dead = false; }
                    if (dead) continue;

                    int ini = 0;
                    try { ini = other.Initiative(); } catch { /* 忽略 */ }

                    targets.Add(new EnemyPathing.Target(op.X, op.Y, other.ActorLocKey(), ini));
                    names.Add(Loc.T(other.ActorLocKey()));
                }
                if (targets.Count == 0) continue;

                // ★ 与多回合共用同一套焦点/落点规则（EnemyPathing = CAIMoveNew 的复刻）：
                //   lowestMoveCostToAttack 升序 → hexDist 升序 → 先攻；
                //   AttackFurthestTarget 时改用 hexDist 降序优先。
                //   以前这里另写了一套"路径距离最近"，两套实现会互相打架（v1.31 的教训）。
                var blocked = new HashSet<(int, int)>(occupied);
                blocked.Remove((e.X, e.Y));                    // 自己站的格子不算阻挡

                int toX, toY, focusIdx;
                EnemyMovePlan plan = EnemyPathing.PlanMove(
                    e.X, e.Y, move, intent.AttackRange,
                    (x, y, r) => Geometry.Reachable(e.Actor, x, y, r),
                    dist, Geometry.HasLOS,
                    targets, blocked,
                    out toX, out toY, out focusIdx,
                    intent.AttackFurthestTarget);

                if (plan == EnemyMovePlan.None) continue;

                var pred = new Prediction
                {
                    Guid = e.Actor.ActorGuid,
                    DisplayName = e.Snap.DisplayName,
                    FromX = e.X,
                    FromY = e.Y,
                    ToX = toX,
                    ToY = toY,
                    MovePoints = move,
                    Initiative = e.Initiative,
                    HasAttack = intent.HasAttack,
                    AttackRange = intent.AttackRange,
                    AttackStrength = intent.AttackStrength,
                    FocusName = focusIdx >= 0 && focusIdx < names.Count ? names[focusIdx] : "(无)",
                    WillMove = toX != e.X || toY != e.Y,
                };
                // 它这次攻击会给我方上什么条件（缴械/中毒/静足…）
                if (intent.AppliesNegative != null)
                {
                    foreach (string c in intent.AppliesNegative)
                    {
                        if (!pred.AppliesNegative.Contains(c)) pred.AppliesNegative.Add(c);
                    }
                }
                list.Add(pred);

                // ★ 占用集随移动推进：先动的怪让出原格、占住新格，
                //   后动的怪不会预测到同一格（旧代码声明了 occupied 却从没更新）。
                if (pred.WillMove)
                {
                    occupied.Remove((e.X, e.Y));
                    occupied.Add((toX, toY));
                    e.X = toX;
                    e.Y = toY;
                }
            }

            return list;
        }

        /// <summary>临时持有的单位引用 + 快照。</summary>
        private sealed class UnitRef
        {
            public CActor Actor;
            public UnitSnapshot Snap;
            public int X, Y;
            public int Initiative;
        }
    }
}

