using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using FHSolver.Model;
using ScenarioRuleLibrary;

namespace FHSolver.Bridge
{
    /// <summary>
    /// 只读读取战局状态 → POCO 快照。
    /// 这是全工程唯一接触游戏类型的地方，Solver 层不引用任何游戏类型。
    /// </summary>
    internal static class StateReader
    {
        public static BattleSnapshot Read()
        {
            var snap = new BattleSnapshot();
            try
            {
                if (!ScenarioManager.IsInTactical)
                {
                    return snap; // Valid=false，不在战斗中
                }

                ScenarioState state = ScenarioManager.CurrentScenarioState;
                CScenario scenario = ScenarioManager.Scenario;
                if (state == null || scenario == null)
                {
                    return snap;
                }

                snap.Valid = true;
                snap.ScenarioId = state.ID;
                snap.RoundNumber = state.RoundNumber;

                // 先 ToList() 拷一份再遍历，避免遍历途中被游戏改动导致异常。
                // 怪物必须取 AllAliveMonsters：AllMonsters 含 DeadEnemies/DeadAllyMonsters 等，
                // 会把已死单位（负血）一起带进来，污染目标选择。
                List<CPlayerActor> players = scenario.PlayerActors?.ToList() ?? new List<CPlayerActor>();
                List<CEnemyActor> monsters = scenario.AllAliveMonsters?.ToList() ?? new List<CEnemyActor>();
                int all = scenario.AllMonsters?.Count ?? monsters.Count;
                snap.DeadMonsterCount = all - monsters.Count;

                foreach (CPlayerActor p in players)
                {
                    if (p == null) continue;
                    UnitSnapshot u = ReadUnit(p, isPlayer: true);
                    CCharacterClass cls = null;
                    try { cls = p.CharacterClass; } catch { /* 忽略 */ }

                    if (cls != null)
                    {
                        try
                        {
                            u.HandCardCount = cls.HandAbilityCards?.Count ?? 0;
                            u.SelectedCardCount = cls.RoundAbilityCardsSelectedInCardSelection?.Count ?? 0;
                            var hand = cls.HandAbilityCards?.ToList();
                            if (hand != null)
                            {
                                foreach (CAbilityCard c in hand)
                                {
                                    // 注意：CBaseCard.ID 是 int，Name 才是字符串
                                    if (c != null) u.HandCardIds.Add(c.Name ?? c.ID.ToString());
                                }
                            }
                        }
                        catch (Exception e)
                        {
                            Plugin.Log?.LogWarning($"[FHSolver] 读取手牌失败: {e.Message}");
                        }

                        snap.PlayerDecks.Add(DeckReader.ReadPlayerDeck(cls, u.Name));
                    snap.PlayerHands.Add(HandReader.ReadHand(cls));

                    // （v0.5.0 曾在这里按最大移动力试算一次可达格数做通路自检；
                    //  P1 现在按具体出牌组合逐个算，这个自检已无意义，删。）
                    }
                    else
                    {
                        snap.PlayerDecks.Add(new ModifierDeckSnapshot { OwnerLabel = u.Name });
                    }

                    snap.Players.Add(u);
                }

                foreach (CEnemyActor m in monsters)
                {
                    if (m == null) continue;
                    snap.Monsters.Add(ReadUnit(m, isPlayer: false));
                }

                snap.MonsterDecks = DeckReader.ReadAllMonsterDecks();
            }
            catch (Exception e)
            {
                Plugin.Log?.LogError($"[FHSolver] 读取战局快照失败: {e.Message}\n{e.StackTrace}");
                snap.Valid = false;
            }
            return snap;
        }

        internal static UnitSnapshot ReadUnit(CActor a, bool isPlayer)
        {
            var u = new UnitSnapshot { IsPlayer = isPlayer };
            try
            {
                u.Guid = a.ActorGuid;
                u.Health = a.Health;
                u.MaxHealth = a.MaxHealth;

                string classId = null;
                try { classId = a.Class?.ID; } catch { /* 忽略 */ }
                u.ClassId = classId ?? "?";

                // 坐标：AStar.Point 的 X/Y 字段
                try
                {
                    AStar.Point pos = a.ArrayIndex;
                    if (pos != null)
                    {
                        u.X = pos.X;
                        u.Y = pos.Y;
                    }
                }
                catch { /* 忽略 */ }

                // ---- 阵营：绝不混为一谈 ----
                // 曾用 AllAliveMonsters 当敌人列表，而它 = Enemies + AllyMonsters + Enemy2Monsters
                // + NeutralMonsters，盟友和中立全混在里面 → 会把盟友当成攻击目标。
                // 现在按 CActor.Type 分类，并且敌对性走游戏自己的 AreActorsAllied。
                try
                {
                    CActor.EType t = a.Type;
                    u.Faction = ToFaction(t);
                    u.FactionName = FactionLabel(u.Faction);
                    u.IsHostileToPlayer = !CActor.AreActorsAllied(CActor.EType.Player, t, null, a);
                }
                catch
                {
                    u.Faction = FactionKind.Unknown;
                    u.FactionName = "未知";
                    u.IsHostileToPlayer = false;   // 拿不准就不当敌人，绝不乱打
                }

                // ---- 先攻 ----
                // 先攻是方法，不是属性
                try { u.Initiative = a.Initiative(); } catch { /* 忽略 */ }
                u.InitiativePredicted = u.Initiative;
                u.InitiativeIsPredicted = false;

                // 怪物在行动牌还没选出来时 Initiative() 返回 0；用下一张行动牌的先攻补上
                if (u.Initiative == 0)
                {
                    try
                    {
                        if (a is CEnemyActor enemy && enemy.MonsterClass != null)
                        {
                            CMonsterAbilityCard next = enemy.MonsterClass.NextAbilityCard;
                            if (next != null && next.Initiative > 0)
                            {
                                u.InitiativePredicted = next.Initiative;
                                u.InitiativeIsPredicted = true;
                            }
                        }
                    }
                    catch { /* 忽略 */ }
                }

                if (isPlayer)
                {
                    var p = a as CPlayerActor;
                    u.Name = p?.CharacterName ?? u.ClassId;
                    try { u.DisplayName = Loc.T(a.ActorLocKey()); } catch { u.DisplayName = u.Name; }
                }
                else
                {
                    var m = a as CEnemyActor;
                    u.Name = u.ClassId + (m != null ? "#" + m.StandeeID : "");
                    try { u.DisplayName = Loc.T(a.ActorLocKey()); } catch { u.DisplayName = u.ClassId; }
                    if (m != null && !string.IsNullOrEmpty(u.DisplayName) && u.DisplayName != u.ClassId)
                    {
                        u.DisplayName = u.DisplayName + "#" + m.StandeeID;   // 同名 standee 要能区分
                    }
                }

                // ---- 怪物意图（M3 入口：CMonsterClass.RoundAbilityCard / NextAbilityCard）----
                // 玩家单位没有行动卡，跳过。怪物在本回合行动牌还没选出时用 NextAbilityCard 顶上，
                // 和上面 InitiativePredicted 的口径保持一致。
                if (!isPlayer)
                {
                    try
                    {
                        if (a is CEnemyActor enemy && enemy.MonsterClass != null)
                        {
                            CMonsterAbilityCard card = enemy.MonsterClass.RoundAbilityCard
                                                    ?? enemy.MonsterClass.NextAbilityCard;
                            if (card != null && card.Action != null)
                            {
                                u.Intent = HandReader.ReadAction(card.Action, "意图");

                                // ★★ 怪物的**射程与目标数不在能力上**！
                                //   反编译实证 CMonsterClass.cs:233 —— 怪物的基础攻击是运行时造的：
                                //     CAbilityAttack.CreateDefaultAttack(
                                //         m_CurrentMonsterStat.Attack,   ← 攻击力
                                //         m_CurrentMonsterStat.Range,    ← 射程（能力上是 0！）
                                //         m_CurrentMonsterStat.Target,   ← 目标数（能力上是 0！）
                                //         isMonster: true)
                                //   ⇒ 能力上读到的 Range/NumberTargets 是 0，必须用
                                //     MonsterClass.Range / MonsterClass.Target 补全 ——
                                //     否则敌人的威胁格算不出来，生存维度整个失效。
                                try
                                {
                                    CMonsterClass mc = enemy.MonsterClass;
                                    if (u.Intent != null && mc != null)
                                    {
                                        int mRange = mc.Range;
                                        int mTarget = mc.Target;
                                        if (u.Intent.AttackRange <= 0 && mRange > 0)
                                            u.Intent.AttackRange = mRange;
                                        if (u.Intent.AttackTargets <= 0 && mTarget > 0)
                                            u.Intent.AttackTargets = mTarget;
                                        if (u.Intent.AttackStrength <= 0 && mc.Attack > 0)
                                            u.Intent.AttackStrength = mc.Attack;
                                        // 移动力同理：怪物的移动不在能力上（能力上恒为 0）
                                        if (u.Intent.MoveStrength <= 0 && mc.Move > 0)
                                            u.Intent.MoveStrength = mc.Move;
                                        // ★ 射程为 0 时兜底成 1（相邻）——
                                        //   射程 0 会让"敌人打不到我"→ 生存维度整个失效。
                                        if (u.Intent.AttackRange <= 0)
                                        {
                                            int mR = mc.Range;
                                            u.Intent.AttackRange = mR > 0 ? mR : 1;
                                        }
                                    }
                                }
                                catch { /* 读不到就维持原样 */ }

                                // ★ 未激活的卡（还在抽牌堆里）运行时强度可能是 0

                                //   （RoundAbilityCard 为空 → 回退 NextAbilityCard = 抽牌堆顶那张）
                                //   → 回退读 **YML 原始卡**（强度是静态写死的数值）
                                if (u.Intent != null && u.Intent.AttackStrength <= 0)
                                {
                                    try
                                    {
                                        CAction ymlAction = card.GetMonsterCardYML?.CardAction;
                                        if (ymlAction != null)
                                        {
                                            ActionSnapshot ymlIntent = HandReader.ReadAction(ymlAction, "意图");
                                            if (ymlIntent != null && ymlIntent.AttackStrength > 0)
                                            {
                                                u.Intent = ymlIntent;
                                                Plugin.Log?.LogInfo(
                                                    $"[FHSolver] 意图强度回退到 YML 卡：{enemy.ActorLocKey()} "

                                                    + $"攻{ymlIntent.AttackStrength}(射程{ymlIntent.AttackRange},目标{ymlIntent.AttackTargets})"
                                                    + $" | 原卡：{HandReader.DescribeAbilities(card.Action)}");
                                            }
                                        }
                                    }
                                    catch { /* 读不到就维持原样 */ }
                                }
                            }

                        }
                    }
                    catch { /* 读不到意图就留空 */ }
                }

                // 护盾：cache=false 避免写回游戏侧的 CachedShieldValue（只读插件不许留下副作用）
                try
                {
                    u.Shield = a.CalculateShield(
                        abilityToShieldFrom: null,
                        ignoreNeutralizeShield: false,
                        includeItemShieldValues: false,
                        cache: false,
                        forceActiveItems: false);
                }
                catch
                {
                    try { u.Shield = a.CachedShieldValue; } catch { /* 忽略 */ }
                }

                // ---- 条件（负面 / 正面）----
                // 缴械 → 不能攻击；静足 → 不能移动；眩晕 → 都不能。
                // 敌人（如精英冰角祭司）先于我们出手时会上这些，
                // 不建模就会给出"其实执行不了"的废方案。
                FillConditions(a, u);
            }
            catch (Exception e)
            {
                Plugin.Log?.LogWarning($"[FHSolver] 读取单位失败: {e.Message}");
            }
            return u;
        }

        /// <summary>
        /// 读单位当前的条件（负面 + 正面）。
        ///
        /// 走 <see cref="CTokens"/>：CActor.m_Tokens 是私有字段，用反射取，
        /// 然后逐个调 HasKey(token) 查 —— 比 GetAllNegativeConditions 稳
        /// （后者在不同版本里签名有出入）。
        ///
        /// 对建模最关键的三个：
        ///   Disarm   缴械 → 攻击类半边用不了
        ///   Immobilize 静足 → 移动类半边用不了
        ///   Stun     眩晕 → 整个半边都用不了
        /// </summary>
        private static void FillConditions(CActor a, UnitSnapshot u)
        {
            try
            {
                if (a == null || u == null) return;

                FieldInfo fi = typeof(CActor).GetField("m_Tokens",
                    BindingFlags.NonPublic | BindingFlags.Instance);
                if (fi == null) return;

                object tokens = fi.GetValue(a);
                if (tokens == null) return;
                System.Type tt = tokens.GetType();

                foreach (string name in Enum.GetNames(typeof(CCondition.ENegativeCondition)))
                {
                    if (name == "NA") continue;
                    object token = Enum.Parse(typeof(CCondition.ENegativeCondition), name);
                    MethodInfo hasKey = tt.GetMethod("HasKey",
                        new[] { typeof(CCondition.ENegativeCondition), typeof(bool) });
                    bool has = false;
                    try
                    {
                        if (hasKey != null)
                        {
                            has = (bool)hasKey.Invoke(tokens, new object[] { token, false });
                        }
                    }
                    catch { /* 该重载不存在就跳过 */ }

                    if (has) u.NegativeConditions.Add(name);
                }

                foreach (string name in Enum.GetNames(typeof(CCondition.EPositiveCondition)))
                {
                    if (name == "NA") continue;
                    object token = Enum.Parse(typeof(CCondition.EPositiveCondition), name);
                    MethodInfo hasKey = tt.GetMethod("HasKey",
                        new[] { typeof(CCondition.EPositiveCondition) });
                    bool has = false;
                    try
                    {
                        if (hasKey != null)
                        {
                            has = (bool)hasKey.Invoke(tokens, new object[] { token });
                        }
                    }
                    catch { /* 该重载不存在就跳过 */ }

                    if (has) u.PositiveConditions.Add(name);
                }
            }
            catch (Exception e)
            {
                Plugin.Log?.LogWarning($"[FHSolver] 读取条件失败: {e.Message}");
            }
        }

        private static FactionKind ToFaction(CActor.EType t)
        {
            switch (t)
            {
                case CActor.EType.Player: return FactionKind.Player;
                case CActor.EType.Enemy: return FactionKind.Enemy;
                case CActor.EType.Enemy2: return FactionKind.Enemy2;
                case CActor.EType.Ally: return FactionKind.Ally;
                case CActor.EType.Neutral: return FactionKind.Neutral;
                case CActor.EType.HeroSummon: return FactionKind.HeroSummon;
                default: return FactionKind.Unknown;
            }
        }

        /// <summary>中文阵营名。</summary>
        public static string FactionLabel(FactionKind f)
        {
            switch (f)
            {
                case FactionKind.Player: return "玩家";
                case FactionKind.Enemy: return "敌人";
                case FactionKind.Enemy2: return "敌人";
                case FactionKind.Ally: return "盟友";
                case FactionKind.Neutral: return "中立";
                case FactionKind.HeroSummon: return "召唤物";
                default: return "未知";
            }
        }
    }
}

using System;
using System.Collections.Generic;
using FHSolver.Model;
using ScenarioRuleLibrary;
using ScenarioRuleLibrary.YML;

namespace FHSolver.Bridge
{
    /// <summary>
    /// 读取攻击修正牌牌堆。
    /// 牌堆顺序 = Remaining[0..n]，翻牌时游戏直接取 [0]，因此这里读到的就是确定的翻牌序列。
    /// </summary>
    internal static class DeckReader
    {
        private static ModifierCardSnapshot ToSnap(AttackModifierYMLData c)
        {
            if (c == null) return null;
            try
            {
                // 优/劣势二选一的 tie-break 要看牌面效果标记（v1.35）
                bool neg = false, add = false;
                try
                {
                    if (c.Card != null)
                    {
                        neg = c.Card.HasNegativeEffect;
                        add = c.Card.HasAdditionalEffect;
                    }
                }
                catch { /* 读不到就当没有，不影响主体 */ }

                return new ModifierCardSnapshot
                {
                    Name = c.Name,
                    MathModifier = c.MathModifier,
                    Shuffle = c.Shuffle,
                    Rolling = c.Rolling,
                    IsCurse = c.IsCurse,
                    IsBless = c.IsBless,
                    HasNegativeEffect = neg,
                    HasAdditionalEffect = add,
                };
            }
            catch (Exception e)
            {
                Plugin.Log?.LogWarning($"[FHSolver] 修正牌读取失败: {e.Message}");
                return null;
            }
        }

        private static void CopyCards(List<AttackModifierYMLData> from, List<ModifierCardSnapshot> to)
        {
            if (from == null) return;
            foreach (AttackModifierYMLData c in from)
            {
                ModifierCardSnapshot s = ToSnap(c);
                if (s != null) to.Add(s);
            }
        }

        /// <summary>读玩家（或英雄召唤物）的角色修正牌堆。</summary>
        public static ModifierDeckSnapshot ReadPlayerDeck(CCharacterClass cls, string label)
        {
            var snap = new ModifierDeckSnapshot { OwnerLabel = label };
            if (cls == null) return snap;
            try
            {
                CopyCards(cls.AttackModifierCards, snap.Remaining);
                CopyCards(cls.DiscardedAttackModifierCards, snap.Discarded);
                snap.ShufflePending = cls.m_ShuffleAttackModifierCards;
            }
            catch (Exception e)
            {
                Plugin.Log?.LogError($"[FHSolver] 读取玩家牌堆[{label}] 失败: {e.Message}");
            }
            return snap;
        }

        /// <summary>读怪物共用牌堆。</summary>
        public static ModifierDeckSnapshot ReadMonsterDeck(CMonsterAttackModifierDeck deck, string label)
        {
            var snap = new ModifierDeckSnapshot { OwnerLabel = label };
            if (deck == null) return snap;
            try
            {
                CopyCards(deck.AttackModifierCards, snap.Remaining);
                CopyCards(deck.DiscardedAttackModifierCards, snap.Discarded);
            }
            catch (Exception e)
            {
                Plugin.Log?.LogError($"[FHSolver] 读取怪物牌堆[{label}] 失败: {e.Message}");
            }
            return snap;
        }

        /// <summary>读四个怪物牌堆（敌方 / 友方 / 敌方2 / 中立）。</summary>
        public static List<ModifierDeckSnapshot> ReadAllMonsterDecks()
        {
            var list = new List<ModifierDeckSnapshot>();
            try
            {
                list.Add(ReadMonsterDeck(MonsterClassManager.EnemyMonsterAttackModifierDeck, "怪物-敌"));
                list.Add(ReadMonsterDeck(MonsterClassManager.AlliedMonsterAttackModifierDeck, "怪物-友"));
                list.Add(ReadMonsterDeck(MonsterClassManager.Enemy2MonsterAttackModifierDeck, "怪物-敌2"));
                list.Add(ReadMonsterDeck(MonsterClassManager.NeutralMonsterAttackModifierDeck, "怪物-中立"));
            }
            catch (Exception e)
            {
                Plugin.Log?.LogError($"[FHSolver] 读取怪物牌堆集合失败: {e.Message}");
            }
            return list;
        }
    }
}

using System.Collections.Generic;

namespace FHSolver.Model
{
    /// <summary>阵营。与 ScenarioRuleLibrary.CActor.EType 一一对应。</summary>
    public enum FactionKind
    {
        Player,
        Enemy,
        Enemy2,
        Ally,
        Neutral,
        HeroSummon,
        Unknown,
    }

    /// <summary>先攻从哪来的 —— 决定输出里要不要标"预测"。</summary>
    public enum InitiativeSource
    {
        /// <summary>游戏已经定好了。</summary>
        Game,

        /// <summary>怪物本回合行动牌还没选出，用 NextAbilityCard 顶上。</summary>
        Predicted,

        /// <summary>来自求解器给该队友的推荐方案（先打出的那张牌）。</summary>
        Plan,
    }

    /// <summary>
    /// 场上一个单位的只读快照。玩家、敌人、盟友、召唤物共用。
    /// </summary>
    public sealed class UnitSnapshot
    {
        public string Guid;
        public string Name;

        /// <summary>
        /// 本地化显示名（简体中文）。求解器的推荐文本一律用这个，不要用 Name。
        /// Name 保留内部标识（ClassId#StandeeID），只在调试行里出现。
        /// </summary>
        public string DisplayName;
        public string ClassId;

        /// <summary>阵营。敌人/敌人2 才是可攻击目标，盟友/中立/召唤物**绝不是**。</summary>
        public FactionKind Faction;

        /// <summary>中文阵营名，用于输出。</summary>
        public string FactionName;

        /// <summary>
        /// 是否对玩家敌对。判定走游戏自己的 CActor.AreActorsAllied(Player, 该单位类型)，
        /// 不自己猜 —— 实测 AllAliveMonsters 把 AllyMonsters / NeutralMonsters 也混进来了，
        /// 直接拿它当敌人列表会把盟友当成攻击目标。
        /// </summary>
        public bool IsHostileToPlayer;

        public bool IsPlayer;
        public int Health;
        public int MaxHealth;
        public int X;
        public int Y;
        public int Initiative;

        /// <summary>
        /// 预测先攻：怪物在本回合行动牌还没选出来时 Initiative() 返回 0，
        /// 这时用 NextAbilityCard.Initiative 顶上。
        /// </summary>
        public int InitiativePredicted;

        /// <summary>InitiativePredicted 是否是预测值（而非游戏已定值）。</summary>
        public bool InitiativeIsPredicted;

        /// <summary>先攻从哪来。输出时据此标注"预测"/"推荐方案"。</summary>
        public InitiativeSource InitiativeFrom = InitiativeSource.Game;

        /// <summary>当前护盾。</summary>
        public int Shield;

        /// <summary>
        /// 该单位当前带有的**负面条件**（Poison / Disarm / Immobilize / Stun …）。
        /// 与 `CCondition.ENegativeCondition` 一一对应。
        ///
        /// 为什么必须建模：敌人（如精英冰角祭司）先于我们出手时会上缴械 / 静足，
        /// 之后我们的方案若还推荐"攻击 / 移动"就是**废方案**。
        /// </summary>
        public List<string> NegativeConditions = new List<string>();

        /// <summary>该单位当前带有的**正面条件**（Strengthen / Ward / Regenerate …）。</summary>
        public List<string> PositiveConditions = new List<string>();

        /// <summary>是否处于某个负面条件下。</summary>
        public bool HasNegative(string cond)
        {
            return NegativeConditions != null && NegativeConditions.Contains(cond);
        }

        /// <summary>是否处于某个正面条件下。</summary>
        public bool HasPositive(string cond)
        {
            return PositiveConditions != null && PositiveConditions.Contains(cond);
        }

        /// <summary>
        /// 该单位用的修正牌堆在 <see cref="P1Context.MonsterDecks"/> 里的下标。
        /// 玩家单位恒为 -1（玩家每人**各自一副**牌堆）；怪物按阵营共用一副：
        ///   0=Enemy 1=Ally 2=Enemy2 3=Neutral。
        /// P5 敌人真实抽牌需要它 —— 同阵营敌人共用一副，必须按顺序依次消耗。
        /// </summary>
        public int DeckIndex = -1;

        /// <summary>
        /// 怪物本回合的行动意图（RoundAbilityCard 已选出的；否则取 NextAbilityCard 预测）。
        /// 玩家单位恒为 null。用来提示"它会先动、会先把距离改掉"。
        /// </summary>
        public ActionSnapshot Intent;

        /// <summary>
        /// 先攻更低（更先动）的单位预计已经对它造成的伤害。
        /// 快照是在出牌阶段拍的，先攻低的队友/敌人动手之后血量才会变 ——
        /// 不补这个就会拿"满血 10"去算一个其实已经被队友打过的目标。
        /// </summary>
        public int PredictedDamage;

        /// <summary>扣掉先动单位预计伤害后的有效血量。</summary>
        public int EffectiveHealth
        {
            get { int h = Health - PredictedDamage; return h < 0 ? 0 : h; }
        }

        // 仅玩家有值
        public int HandCardCount;
        public int SelectedCardCount;
        public List<string> HandCardIds = new List<string>();

        /// <summary>
        /// 阵营 → 怪物共享牌堆下标。与 DeckReader.ReadAllMonsterDecks() 的返回顺序一致。
        /// 玩家自己的召唤物（HeroSummon）不算怪物牌堆 → 返回 -1。
        /// </summary>
        public static int DeckIndexForFaction(FactionKind f)
        {
            switch (f)
            {
                case FactionKind.Enemy:   return 0;
                case FactionKind.Ally:    return 1;
                case FactionKind.Enemy2:  return 2;
                case FactionKind.Neutral: return 3;
                default:                  return -1;
            }
        }

        public override string ToString()
        {
            // 带短 Guid：StandeeID 不唯一（同一怪物类的多个 standee 会重号），
            // 唯一标识是 ActorGuid，M3 选目标必须以它为准。
            string g = string.IsNullOrEmpty(Guid) ? "?" : Guid.Substring(0, 8);
            string shown = string.IsNullOrEmpty(DisplayName) ? Name : DisplayName;
            return $"{shown}[{FactionName}] {Health}/{MaxHealth}"
                 + (PredictedDamage > 0 ? $"(-{PredictedDamage}→{EffectiveHealth})" : "")
                 + $" 先攻{Initiative} #{g}";
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using FHSolver.Model;

namespace FHSolver.Solver
{
    /// <summary>
    /// 状态推进器（P5）——把一个方案"执行"掉，得到下一回合的世界状态。
    ///
    /// ⚠ 这是**简化模拟**，不是精确复刻游戏的回合流程：
    ///   · 玩家回合：按方案应用位移、伤害、击杀、弃牌、牌堆推进 —— 这部分是准确的
    ///   · 敌人回合：**已接上真实修正牌抽牌**（见 RunEnemyTurn），
    ///     伤害 = 意图攻击力代入**确切会翻出的那张牌**。
    ///     但**不模拟它的寻路**（用 射程+移动力 取上界粗判够不够得着）
    ///   · 队友回合：不推进（队友位置保持不变）
    ///   窗口「多回合」页会明说这一点，避免玩家把它当成精确预测。
    /// </summary>
    internal static class StateAdvancer
    {
        /// <summary>执行一个玩家方案 → 新状态。</summary>
        public static WorldState Apply(WorldState cur, TurnPlan plan)
        {
            WorldState st = cur.Clone();
            if (plan == null) return st;

            // ---- 位移 ----
            st.MyX = plan.FinalX;
            st.MyY = plan.FinalY;

            // ---- 危险地形自伤 ----
            if (plan.SelfHazardDamage > 0)
            {
                st.MyHealth -= plan.SelfHazardDamage;
                st.HazardTaken += plan.SelfHazardDamage;
            }

            // ---- 攻击与击杀 ----
            foreach (AttackChoice a in plan.Attacks)
            {
                if (a == null || string.IsNullOrEmpty(a.TargetGuid)) continue;

                UnitSnapshot target = FindUnit(st, a.TargetGuid);
                if (target == null) continue;

                int dmg = Math.Max(0, a.Damage);
                target.Health -= dmg;
                st.TotalDamage += dmg;
                st.TotalXp += EstimateXp(dmg, target);

                // ⚠ AttackChoice.Damage 已经是**减过护盾**的值（DamageModel.Compute），
                //   护盾按每次攻击独立生效、不会在本回合被"抽干"，
                //   所以这里不再重复扣护盾（旧代码那行算式恒为 0，等于死代码）。

                if (target.Health <= 0)
                {
                    target.Health = 0;
                    st.TotalKills++;
                    st.Monsters.Remove(target);
                }
            }

            // ---- 战役目标分（终点踩到的东西）----
            foreach (LootSpot sp in st.LootSpots)
            {
                if (sp.X == plan.FinalX && sp.Y == plan.FinalY)
                {
                    st.GoalValue += sp.Value;
                    st.LootSpots.Remove(sp);
                    break;
                }
            }

            // ---- 弃掉打出的两张牌 ----
            // 先攻与执行顺序解耦后，打出的是"上半位那张 + 下半位那张"，
            // 与先执行哪个无关，所以按 CardIndex 弃。
            st.Hand.RemoveAll(c => c == null);
            if (plan.TopCardIndex >= 0 && plan.TopCardIndex < st.Hand.Count)
            {
                st.Hand.RemoveAt(plan.TopCardIndex);
            }
            int bottomIdx = plan.BottomCardIndex;
            if (plan.TopCardIndex >= 0 && plan.TopCardIndex < bottomIdx) bottomIdx--;
            if (bottomIdx >= 0 && bottomIdx < st.Hand.Count)
            {
                st.Hand.RemoveAt(bottomIdx);
            }

            // ---- 修正牌堆推进（本回合抽了几张）----
            int consumed = 0;
            foreach (AttackChoice a in plan.Attacks)
            {
                if (a != null) consumed += Math.Max(0, a.CardsConsumed);
            }
            AdvanceDeck(st.Deck, consumed);

            st.Round = cur.Round + 1;

            if (st.MyHealth <= 0)
            {
                st.MyHealth = 0;
                st.Dead = true;
            }
            return st;
        }

        /// <summary>
        /// 敌人回合 —— **真实寻路 + 真实抽修正牌**（P5 精确化）。
        ///
        /// 两处都依据反编译实证：
        ///   · 抽牌：修正牌堆是**确定序列**，DrawAttackModifierCard 直接取 current[0]，
        ///     零 RNG 消耗，实测 354/354 全中 → 能算出它**确切翻出哪张牌**
        ///   · 寻路：CAIMoveNew 全程确定性（Random 出现 0 次），
        ///     焦点 = 能打到它所需**移动代价**最小者，落点 = 能打到焦点且代价最小的格子
        ///
        /// 与上一版的区别：
        ///   旧：够不着判定用 `dist <= AttackRange + MoveStrength` —— 纯几何，**会高估**
        ///       （隔一堵墙、或压根没有路，也会被算成"能打到你"）
        ///   新：真的去寻路，看**是否存在**一个可达格能打到目标
        ///       → 考虑了地形（困难地形多耗移动力）、占用（别的单位挡路）、视线（墙）
        ///
        /// ⚠ 仍保留的简化：
        ///   · 贴近目标是"离**焦点本人**最近的可达格"，真实代码是"离最佳攻击位最近"
        ///     （攻击位本来就在焦点旁边，绝大多数场景等价）
        ///   · 只结算"打我"那一下；打队友时只消耗牌、不计我掉血
        ///   · 不模拟敌人对我方的优/劣势
        ///   · 不模拟移动力不足以走完时的"部分路径"细节
        /// </summary>
        /// <returns>本回合敌人对我造成的每一次打击（供输出展示）</returns>
        public static List<EnemyStrike> RunEnemyTurn(WorldState st, int myInitiative)
        {
            var strikes = new List<EnemyStrike>();
            if (st == null || st.Dead) return strikes;

            // 先动先结算 —— 同阵营共用一副牌堆，顺序错了牌就翻错
            var actors = new List<UnitSnapshot>();
            foreach (UnitSnapshot e in st.Monsters)
            {
                if (e == null) continue;
                if (e.Initiative >= myInitiative) continue;   // 它后动，这回合不碰我
                actors.Add(e);
            }
            actors.Sort((a, b) => a.Initiative.CompareTo(b.Initiative));

            // 占用集：随着敌人移动动态更新（先动的会让出原格、占住新格）
            var occupied = new HashSet<(int, int)> { (st.MyX, st.MyY) };
            foreach (UnitSnapshot u in st.Monsters) if (u != null) occupied.Add((u.X, u.Y));
            foreach (UnitSnapshot u in st.Others) if (u != null) occupied.Add((u.X, u.Y));

            foreach (UnitSnapshot e in actors)
            {
                ActionSnapshot it = e.Intent;
                if (it == null || !it.HasAttack) continue;
                if (it.AttackStrength <= 0) continue;

                // ---- 候选目标：我排第 0，其余是队友/盟友 ----
                // 目标列表：带上先攻（同距时 tie-break，照抄 ActorInitiativeComparer）
                var targets = new List<EnemyPathing.Target>
                {
                    new EnemyPathing.Target(st.MyX, st.MyY, "我", myInitiative)
                };
                foreach (UnitSnapshot o in st.Others)
                {
                    if (o == null || o.IsHostileToPlayer) continue;
                    targets.Add(new EnemyPathing.Target(o.X, o.Y, o.DisplayName, o.Initiative));
                }

                // 它自己站的格子不算阻挡（否则永远走不出去）
                var blocked = new HashSet<(int, int)>(occupied);
                blocked.Remove((e.X, e.Y));

                int move = it.HasMove ? it.MoveStrength : 0;

                EnemyMovePlan plan = EnemyPathing.PlanMove(
                    e.X, e.Y, move, it.AttackRange,
                    st.Reachable, st.RangeDistance, st.HasLOS,
                    targets, blocked,
                    out int toX, out int toY, out int focusIdx,
                    it.AttackFurthestTarget);

                if (plan == EnemyMovePlan.None) continue;

                bool moved = toX != e.X || toY != e.Y;
                if (moved)
                {
                    occupied.Remove((e.X, e.Y));
                    occupied.Add((toX, toY));
                    e.X = toX;
                    e.Y = toY;
                }

                // ★ 够不着 → 它**照样会逼近**（真实 AI 的 fallback，不是原地不动），
                //   但这回合不出手、也不抽修正牌。
                //   对玩家很重要：它靠过来了，下回合多半就能打到你。
                if (plan == EnemyMovePlan.Approach)
                {
                    strikes.Add(new EnemyStrike
                    {
                        AttackerName = e.DisplayName,
                        Initiative = e.Initiative,
                        Damage = 0,
                        CardsText = "（未出手）",
                        Approx = false,
                        Moved = moved,
                        FromX = e.X,
                        FromY = e.Y,
                        ApproachOnly = true,
                    });
                    continue;
                }

                // ---- 抽牌：只要它出手了就抽（不管打的是谁）----
                ModifierDeckSnapshot deck = GetDeck(st, e.DeckIndex);
                int dmg;
                string cardText;
                bool approx;

                List<ModifierCardSnapshot> drawn = null;
                int consumed = 0;
                if (deck != null && deck.Remaining.Count > 0)
                {
                    drawn = ModifierDraw.Simulate(deck.Remaining, 0, AdvStatus.None,
                        it.AttackStrength, out consumed);
                }

                if (drawn != null && drawn.Count > 0)
                {
                    dmg = DamageModel.ComputePreShield(it.AttackStrength, drawn);
                    cardText = string.Join(" ", drawn.Select(c => c != null ? c.ToString() : "?"));
                    approx = false;
                    ConsumeDeck(deck, drawn, consumed);
                }
                else
                {
                    // 牌堆见底会触发洗牌 → 顺序不可知，退化成意图估算并标记
                    dmg = it.AttackStrength;
                    cardText = deck == null ? "（无牌堆数据）" : "（牌堆见底，待洗）";
                    approx = true;
                    st.EnemyDeckExhausted = true;
                }

                if (focusIdx != 0) continue;    // 打的是队友，不掉我血

                // ---- 护盾先吃，再扣血 ----
                if (st.MyShield > 0)
                {
                    int absorbed = Math.Min(st.MyShield, Math.Max(0, dmg));
                    st.MyShield -= absorbed;
                    dmg -= absorbed;
                }
                if (dmg < 0) dmg = 0;
                st.MyHealth -= dmg;

                strikes.Add(new EnemyStrike
                {
                    AttackerName = e.DisplayName,
                    Initiative = e.Initiative,
                    Damage = dmg,
                    CardsText = cardText,
                    Approx = approx,
                    Moved = moved,
                    FromX = moved ? toX : e.X,
                    FromY = moved ? toY : e.Y,
                });

                if (st.MyHealth <= 0)
                {
                    st.MyHealth = 0;
                    st.Dead = true;
                    st.KilledBy = e.DisplayName;
                    return strikes;
                }
            }
            return strikes;
        }

        private static ModifierDeckSnapshot GetDeck(WorldState st, int index)
        {
            if (st == null || index < 0 || index >= st.EnemyDecks.Count) return null;
            return st.EnemyDecks[index];
        }

        /// <summary>把本次抽到的牌从牌堆顶移走；含 Shuffle 牌则置待洗标记。</summary>
        private static void ConsumeDeck(ModifierDeckSnapshot deck,
            List<ModifierCardSnapshot> drawn, int consumed)
        {
            if (deck == null || consumed <= 0) return;

            for (int i = 0; i < consumed && deck.Remaining.Count > 0; i++)
            {
                ModifierCardSnapshot c = deck.Remaining[0];
                deck.Remaining.RemoveAt(0);
                deck.Discarded.Add(c);
            }

            // ×0 / ×2 抽到只置位，回合末才洗（MODIFIER.md 实证）
            foreach (ModifierCardSnapshot c in drawn)
            {
                if (c != null && c.Shuffle) deck.ShufflePending = true;
            }
        }

        private static int EstimateXp(int damage, UnitSnapshot target)
        {
            // 经验按"造成的伤害"粗估（真实规则是杀敌给的经验更多），
            // 这里只用于多回合路线的相对比较，不需要绝对精确。
            return damage;
        }

        private static UnitSnapshot FindUnit(WorldState st, string guid)
        {
            foreach (UnitSnapshot u in st.Monsters) if (u.Guid == guid) return u;
            foreach (UnitSnapshot u in st.Others) if (u.Guid == guid) return u;
            return null;
        }

        private static void AdvanceDeck(ModifierDeckSnapshot deck, int count)
        {
            if (deck == null || count <= 0) return;
            for (int i = 0; i < count; i++)
            {
                if (deck.Remaining.Count == 0) { deck.ShufflePending = true; break; }
                deck.Discarded.Add(deck.Remaining[0]);
                deck.Remaining.RemoveAt(0);
            }
        }

        /// <summary>六边形距离（axial）。</summary>
        private static int HexDist(int x1, int y1, int x2, int y2)
        {
            int ax = x1 - (y1 - 1) / 2;
            int ay = y1;
            int bx = x2 - (y2 - 1) / 2;
            int by = y2;
            int d = Math.Abs(ax - bx) + Math.Abs(ay - by) + Math.Abs((ax + ay) - (bx + by));
            return d / 2;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Reflection;
using FHSolver.Model;
using ScenarioRuleLibrary;

namespace FHSolver.Bridge
{
    /// <summary>
    /// 战役目标读取（P2）—— **只读**。
    ///
    /// 数据来源全部是 `ScenarioState` 上的公开属性，不需要反射：
    ///   · `WinObjectives` / `LoseObjectives` → 使命目标与失败条件
    ///   · `ChestProps` → 宝箱（Chest / GoalChest）
    ///   · `LootProps`   → 金币堆 / 战利品袋（MoneyToken）
    ///   · `ResourceProps` → 资源
    ///   · `LootDeck`（`List<byte>`）→ 下一次捡拾会拿到什么
    ///
    /// 战利品可预测性的关键（MISSION_AND_LOOT.md §4.1）：
    ///   `CLootDeck.DrawNext` 直接取 `deck[0]` 作为 `AllCards` 下标，
    ///   **抽完放回末尾**（循环使用）。所以求解器在捡拾前就知道会拿到什么。
    /// </summary>
    internal static class GoalReader
    {
        // ---- 战利品价值（按优先级链换算的评分单位）----
        // 使命目标 > 捡拾装备/宝箱 > 专长 > 战绩 > 经验 > 战利品袋(材料)
        private const int V_CHEST = 120;       // 宝箱 / 装备 → 第 2 档
        private const int V_LOOT_ITEM = 120;   // 袋子开出装备 → 也升到第 2 档
        private const int V_LOOT_MAT = 15;     // 袋子开出材料 → 第 6 档
        private const int V_RESOURCE = 15;     // 资源 → 第 6 档
        private const int V_QUEST = 100;       // 任务物品

        /// <summary>读取战役目标。</summary>
        public static GoalSnapshot Read()
        {
            var snap = new GoalSnapshot();
            try
            {
                ScenarioState state = ScenarioManager.CurrentScenarioState;
                if (state == null) return snap;

                ReadObjectives(state, snap);
                ReadLootSpots(state, snap);
                ReadNextLoot(state, snap);
            }
            catch (Exception e)
            {
                Plugin.Log?.LogWarning($"[FHSolver] 读取战役目标失败: {e.Message}");
            }
            return snap;
        }

        // ---- ① 使命目标 ----

        private static void ReadObjectives(ScenarioState state, GoalSnapshot snap)
        {
            try
            {
                foreach (CObjective o in state.WinObjectives ?? new List<CObjective>())
                {
                    if (o == null) continue;
                    ObjectiveSnapshot s = ToSnapshot(o, isWin: true);
                    snap.Objectives.Add(s);
                    if (s.WinsDespiteExhaustion) snap.AnyWinsDespiteExhaustion = true;
                }
            }
            catch (Exception e)
            {
                Plugin.Log?.LogWarning($"[FHSolver] 读取胜利目标失败: {e.Message}");
            }

            try
            {
                foreach (CObjective o in state.LoseObjectives ?? new List<CObjective>())
                {
                    if (o == null) continue;
                    snap.Objectives.Add(ToSnapshot(o, isWin: false));
                }
            }
            catch (Exception e)
            {
                Plugin.Log?.LogWarning($"[FHSolver] 读取失败条件失败: {e.Message}");
            }
        }

        private static ObjectiveSnapshot ToSnapshot(CObjective o, bool isWin)
        {
            var s = new ObjectiveSnapshot
            {
                IsWin = isWin,
                TypeName = o.ObjectiveType.ToString(),
                IsComplete = o.IsComplete,
                UnableToComplete = o.UnableToComplete,
                IsActive = o.IsActive,
                IsOptional = o.IsOptional,
                EnoughToWinAlone = o.EnoughToWinAlone,
                WinsDespiteExhaustion = o.WinsDespiteExhaustion,
                IsHidden = o.IsHidden,
            };

            // 目标描述：CustomLocKey 是本地化键
            try
            {
                if (!string.IsNullOrEmpty(o.CustomLocKey))
                {
                    s.Text = Loc.T(o.CustomLocKey);
                }
            }
            catch { /* 取不到就留空 */ }

            return s;
        }

        // ---- ② 地上的可捡拾物 ----

        private static void ReadLootSpots(ScenarioState state, GoalSnapshot snap)
        {
            // 宝箱（Chest / GoalChest）→ 第 2 档
            AddSpots(snap, SafeProps(state, "ChestProps"),
                ScenarioManager.ObjectImportType.Chest, V_CHEST, "宝箱");

            // 金币堆 / 战利品袋 → 价值取决于下一张是不是装备
            int lootValue = snap.NextLootIsItem ? V_LOOT_ITEM : V_LOOT_MAT;
            AddSpots(snap, SafeProps(state, "LootProps"),
                ScenarioManager.ObjectImportType.MoneyToken, lootValue, "战利品袋");

            // 资源
            AddSpots(snap, SafeProps(state, "ResourceProps"),
                ScenarioManager.ObjectImportType.Resource, V_RESOURCE, "资源");
        }

        private static void AddSpots(GoalSnapshot snap, List<CObjectProp> props,
            ScenarioManager.ObjectImportType type, int value, string name)
        {
            if (props == null) return;
            foreach (CObjectProp p in props)
            {
                if (p == null) continue;
                int x, y;
                if (!TryTile(p, out x, out y)) continue;

                LootSpotKind kind = KindOf(p.ObjectType);
                snap.LootSpots.Add(new LootSpot
                {
                    Kind = kind,
                    KindName = KindName(kind, name),
                    X = x,
                    Y = y,
                    Value = value,
                });
            }
        }

        private static LootSpotKind KindOf(ScenarioManager.ObjectImportType t)
        {
            switch (t)
            {
                case ScenarioManager.ObjectImportType.Chest:
                case ScenarioManager.ObjectImportType.GoalChest:
                    return LootSpotKind.Chest;
                case ScenarioManager.ObjectImportType.MoneyToken:
                    return LootSpotKind.MoneyToken;
                case ScenarioManager.ObjectImportType.Resource:
                    return LootSpotKind.Resource;
                default:
                    return LootSpotKind.Unknown;
            }
        }

        private static string KindName(LootSpotKind k, string fallback)
        {
            switch (k)
            {
                case LootSpotKind.Chest: return "宝箱";
                case LootSpotKind.MoneyToken: return "战利品袋";
                case LootSpotKind.Resource: return "资源";
                case LootSpotKind.QuestItem: return "任务物品";
                default: return string.IsNullOrEmpty(fallback) ? "物件" : fallback;
            }
        }

        private static bool TryTile(CObjectProp p, out int x, out int y)
        {
            x = -1;
            y = -1;
            try
            {
                CTile t = p.PropTile;
                if (t == null || t.m_ArrayIndex == null) return false;
                x = t.m_ArrayIndex.X;
                y = t.m_ArrayIndex.Y;
                return true;
            }
            catch
            {
                return false;
            }
        }

        private static List<CObjectProp> SafeProps(ScenarioState state, string propName)
        {
            try
            {
                PropertyInfo pi = typeof(ScenarioState).GetProperty(
                    propName, BindingFlags.Public | BindingFlags.Instance);
                if (pi == null) return null;
                return pi.GetValue(state, null) as List<CObjectProp>;
            }
            catch
            {
                return null;
            }
        }

        // ---- ③ 下一张战利品 ----

        private static void ReadNextLoot(ScenarioState state, GoalSnapshot snap)
        {
            try
            {
                List<byte> deck = state.LootDeck;
                if (deck == null || deck.Count == 0) return;

                snap.HasLootDeck = true;

                // deck[0] 是下一次捡拾会抽到的牌（下标到 CLootDeck.AllCards）；0 是分隔符
                byte idx = deck[0];
                if (idx == 0) return;

                LootCard? lc = PeekLootCard(idx);
                if (!lc.HasValue) return;

                snap.NextLootIsItem = lc.Value.Type == LootCard.EType.RandomItem;
                snap.NextLootName = snap.NextLootIsItem ? "随机装备" : lc.Value.Type.ToString();

                // 若下一张是装备，已加过的战利品袋要按装备的价值重算
                if (snap.NextLootIsItem)
                {
                    foreach (LootSpot s in snap.LootSpots)
                    {
                        if (s.Kind == LootSpotKind.MoneyToken) s.Value = V_LOOT_ITEM;
                    }
                }
            }
            catch (Exception e)
            {
                Plugin.Log?.LogWarning($"[FHSolver] 读取战利品牌堆失败: {e.Message}");
            }
        }

        /// <summary>按下标取一张战利品卡（不改动牌堆）。</summary>
        private static LootCard? PeekLootCard(byte index)
        {
            try
            {
                // CLootDeck.AllCards 是静态表
                FieldInfo fi = typeof(CLootDeck).GetField("AllCards",
                    BindingFlags.Public | BindingFlags.Static);
                if (fi == null) return null;

                var all = fi.GetValue(null) as List<LootCard>;
                if (all == null || index >= all.Count) return null;
                return all[index];
            }
            catch
            {
                return null;
            }
        }
    }
}

using System.Collections.Generic;

namespace FHSolver.Model
{
    /// <summary>
    /// 地上可捡拾的东西。对应 `ScenarioManager.ObjectImportType`。
    /// 价值按用户定的优先级链换算：
    ///   使命目标 > 捡拾装备/宝箱 > 专长任务 > 巅峰战绩 > 经验值 > 战利品袋(材料)
    /// </summary>
    public enum LootSpotKind
    {
        /// <summary>宝箱（Chest / GoalChest）→ 优先级 2</summary>
        Chest,

        /// <summary>金币堆 / 战利品袋（MoneyToken）→ 优先级 6；但若下一张是装备则升到第 2 档</summary>
        MoneyToken,

        /// <summary>资源（Resource）→ 优先级 6</summary>
        Resource,

        /// <summary>任务物品（CarryableQuestItem）</summary>
        QuestItem,

        Unknown,
    }

    /// <summary>地上一处可以捡的东西。</summary>
    public sealed class LootSpot
    {
        public LootSpotKind Kind = LootSpotKind.Unknown;
        public string KindName = "";
        public int X;
        public int Y;

        /// <summary>
        /// 捡它的价值（已按优先级链换算成评分单位）。
        /// 战利品袋的价值取决于 `LootDeck` 下一张是不是装备 —— 见 MISSION_AND_LOOT.md §4.3。
        /// </summary>
        public int Value;

        public override string ToString()
        {
            return $"{KindName}@({X},{Y}) 价值{Value}";
        }
    }

    /// <summary>一个使命目标（或失败条件）的只读快照。</summary>
    public sealed class ObjectiveSnapshot
    {
        /// <summary>目标类型名（KillAllEnemies / LootX / ActorReachPosition … 共 22 种）。</summary>
        public string TypeName = "";

        /// <summary>true = 胜利目标；false = 失败条件。</summary>
        public bool IsWin;

        public bool IsComplete;
        public bool UnableToComplete;
        public bool IsActive;

        /// <summary>可选目标 —— 不完成也能通关。</summary>
        public bool IsOptional;

        /// <summary>单独完成即算通关（多个目标之间"任一即可"）。</summary>
        public bool EnoughToWinAlone;

        /// <summary>力竭仍算赢 → 可以放心耗尽手牌。</summary>
        public bool WinsDespiteExhaustion;

        public bool IsHidden;

        /// <summary>展示文本（本地化后的目标描述）。</summary>
        public string Text = "";

        public override string ToString()
        {
            var tags = new List<string>();
            if (IsWin) tags.Add("胜利");
            else tags.Add("失败条件");
            if (IsComplete) tags.Add("已完成");
            if (UnableToComplete) tags.Add("已无法完成");
            if (!IsActive) tags.Add("未生效");
            if (IsOptional) tags.Add("可选");
            if (EnoughToWinAlone) tags.Add("单独即可通关");
            if (WinsDespiteExhaustion) tags.Add("力竭仍赢");
            return $"[{string.Join("/", tags)}] {TypeName}"
                 + (string.IsNullOrEmpty(Text) ? "" : " — " + Text);
        }
    }

    /// <summary>
    /// 战役目标快照（P2）。
    ///
    /// 全部来自 `ScenarioState`，只读：
    ///   · `WinObjectives` / `LoseObjectives`
    ///   · `ChestProps` / `LootProps` / `ResourceProps`
    ///   · `LootDeck`（`List<byte>`，`deck[0]` = 下一次捡拾会抽到的牌）
    /// </summary>
    public sealed class GoalSnapshot
    {
        public List<ObjectiveSnapshot> Objectives = new List<ObjectiveSnapshot>();
        public List<LootSpot> LootSpots = new List<LootSpot>();

        /// <summary>下一次捡拾会拿到什么（已本地化）。</summary>
        public string NextLootName = "?";

        /// <summary>下一张是不是随机装备 —— 是的话战利品袋要按"装备"优先级（第 2 档）算。</summary>
        public bool NextLootIsItem;

        public bool HasLootDeck;

        /// <summary>有没有"力竭仍算赢"的目标（有就可以放心打光手牌）。</summary>
        public bool AnyWinsDespiteExhaustion;
    }
}

