		private static void RecordExpectation(
			BattleSnapshot snap, int myHp, List<AbilityCardSnapshot> hand,
			TurnLedger.Fingerprint fp)
		{
			if (snap == null) return;
			List<UnitSnapshot> monsters = snap.Monsters ?? new List<UnitSnapshot>();
